/** @summary Require actual native behavior. @param value Observation. @param message Fixed diagnostic. */
void Check(bool value,const char* message){++checks;if(!value)throw std::runtime_error(message);}
/** @summary Bound stateful fixture polling without replaying a successful predicate. @param predicate Actual observation. @param message Failure evidence. */
template<class F> void Await(F predicate,const char* message){const auto end=std::chrono::steady_clock::now()+5s;bool done=predicate();while(!done&&std::chrono::steady_clock::now()<end){std::this_thread::sleep_for(1ms);done=predicate();}Check(done,message);}
/** @summary Own a genuine finite native pause. */
struct Gate final{std::mutex mutex;std::condition_variable changed;bool entered{},released{};
    /** @summary Resume paused native work during unwinding. */
    ~Gate(){Release();}
    /** @summary Pause first visit outside runtime guards. */
    void Pause(){std::unique_lock lock(mutex);if(entered)return;entered=true;changed.notify_all();if(!changed.wait_for(lock,5s,[&]{return released;}))throw std::runtime_error("VM retirement pause timeout");}
    /** @summary Observe actual entry. */
    void Wait(){std::unique_lock lock(mutex);Check(changed.wait_for(lock,5s,[&]{return entered;}),"actual VM retirement pause reached");}
    /** @summary Release once. */
    void Release(){std::lock_guard lock(mutex);released=true;changed.notify_all();}
};
